// carts/jetchess/art/metrics.h
//
// What each piece's finished drawing measures — generated by
// scripts/jetchess_art.py from the pictures themselves, after it has drawn
// them. Do not edit: edit the script and run it.
//
// Heights and widths INCLUDE the rim the bake grows around each piece, so
// they are what a player sees, not what the outline was.
#ifndef JETCHESS_ART_METRICS_H
#define JETCHESS_ART_METRICS_H

#include "engine/chess.h"

// Indexed by piece KIND (JC_PAWN..JC_KING), so a lookup needs no table of
// its own; slot 0 is the empty square and is never asked for.
static const uint8_t JC_PIECE_INK_HEIGHT[JC_KINDS] = {
    0, 40, 52, 55, 49, 58, 61,
};

static const uint8_t JC_PIECE_INK_WIDTH[JC_KINDS] = {
    0, 30, 40, 34, 38, 40, 42,
};

// Where a piece's ink begins inside its 64-pixel cell, counting down from
// the cell's top. Every piece's ink ENDS at the same row, because they all
// stand on one baseline; this is the only part that differs.
static const uint8_t JC_PIECE_INK_TOP[JC_KINDS] = {
    0, 22, 10, 7, 13, 4, 1,
};

// The LAST row every piece's ink covers: the underside of the foot with
// the rim grown around it. They all share it, because they all stand on
// one baseline. A shadow on the ground goes here, and nowhere else.
#define JC_PIECE_FOOT_ROW 61

#endif // JETCHESS_ART_METRICS_H
